using System.Threading.Channels;

// the general channel: bounded, multi-reader/multi-writer, async
var channel = Channel.CreateBounded<int>(new BoundedChannelOptions(256)
{ FullMode = BoundedChannelFullMode.Wait });   // Wait = backpressure

await channel.Writer.WriteAsync(job);           // suspends/backpressures when full
var result = await channel.Reader.ReadAsync();  // awaits when empty
channel.Writer.Complete();                       // the PRODUCER closes;
// readers drain what remains, then ReadAsync returns false
await foreach (var item in channel.Reader.ReadAllAsync()) Process(item);

